output_text:
[
  {
    "id": "no_cart_single_file_shelf_aisle",
    "text": "Shopping carts are forbidden in single-file shelf aisles where opposing shelves leave only one cell of horizontal clearance.",
    "abstraction": {
      "state_properties": {
        "tight_horizontal_clearance": {
          "le": [
            "freeWidthH",
            1
          ]
        },
        "opposing_side_shelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "single_file_shelf_aisle": {
          "and": [
            "tight_horizontal_clearance",
            "opposing_side_shelves"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "single_file_shelf_aisle"
        ]
      }
    }
  },
  {
    "id": "no_enter_tight_aisle_with_cart",
    "text": "An agent must not move a cart from an open aisle into a tight shelf aisle.",
    "abstraction": {
      "state_properties": {
        "open_aisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        },
        "tight_shelf_aisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "enter_tight_shelf_aisle_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE",
              "open_aisle"
            ]
          },
          "post": "tight_shelf_aisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enter_tight_shelf_aisle_with_cart"
    }
  },
  {
    "id": "park_at_shelf_aisle_mouth",
    "text": "Upon arriving with a cart at the mouth of a narrow shelf aisle, the agent is obliged to park the cart there before continuing.",
    "abstraction": {
      "state_properties": {
        "wide_cross_aisle": {
          "and": [
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        },
        "shelf_aisle_mouth": {
          "and": [
            "at(3,3)",
            "wide_cross_aisle",
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "arrive_at_shelf_aisle_mouth_with_cart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": {
            "and": [
              "shelf_aisle_mouth",
              "hasCart"
            ]
          }
        },
        "park_cart_at_shelf_aisle_mouth": {
          "pre": {
            "and": [
              "shelf_aisle_mouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "and": [
              "shelf_aisle_mouth",
              {
                "not": "hasCart"
              }
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "arrive_at_shelf_aisle_mouth_with_cart",
      "discharge": "park_cart_at_shelf_aisle_mouth"
    }
  },
  {
    "id": "recover_parked_cart",
    "text": "After parking a cart at a shelf-aisle mouth, the agent is obliged to recover that cart before leaving the area.",
    "abstraction": {
      "state_properties": {
        "cart_parking_mouth": {
          "and": [
            "at(3,3)",
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "park_cart": {
          "pre": {
            "and": [
              "cart_parking_mouth",
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "and": [
              "cart_parking_mouth",
              {
                "not": "hasCart"
              }
            ]
          }
        },
        "recover_cart": {
          "pre": {
            "and": [
              "cart_parking_mouth",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": {
            "and": [
              "cart_parking_mouth",
              "hasCart"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "park_cart",
      "discharge": "recover_cart"
    }
  },
  {
    "id": "no_cartless_roaming",
    "text": "Agents may move without a cart only inside the cart-free shopping pocket consisting of the narrow shelf aisle and its cart-parking mouth.",
    "abstraction": {
      "state_properties": {
        "narrow_shelf_aisle": {
          "and": [
            "adjShelf",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "parking_mouth": {
          "and": [
            "at(3,3)",
            {
              "ge": [
                "freeWidthH",
                6
              ]
            }
          ]
        },
        "cart_free_shopping_pocket": {
          "or": [
            "narrow_shelf_aisle",
            "parking_mouth"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "MOVE",
          {
            "not": "hasCart"
          },
          {
            "not": "cart_free_shopping_pocket"
          }
        ]
      }
    }
  },
  {
    "id": "hands_free_shelf_interaction",
    "text": "When interacting with shelves in a shelf aisle, the agent must be hands-free and therefore must not be holding a cart.",
    "abstraction": {
      "state_properties": {
        "shelf_service_position": {
          "and": [
            "adjShelf",
            {
              "or": [
                "shelfN",
                "shelfS",
                "shelfE",
                "shelfW"
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "shelf_service_position",
          "hasCart"
        ]
      }
    }
  },
  {
    "id": "must_acquire_cart_at_cart_bay",
    "text": "At the start of a shopping trip, the agent is obliged to acquire a cart from the cart bay before proceeding through the store.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_bay": {
          "and": [
            "at(1,7)",
            {
              "ge": [
                "freeWidthH",
                6
              ]
            },
            {
              "ge": [
                "freeWidthV",
                5
              ]
            }
          ]
        }
      },
      "events": {
        "take_cart_from_bay": {
          "pre": {
            "and": [
              "entrance_cart_bay",
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": {
            "and": [
              "entrance_cart_bay",
              "hasCart"
            ]
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_cart_from_bay"
    }
  },
  {
    "id": "exit_with_cart",
    "text": "Agents are forbidden to exit the supermarket without a cart, even if they temporarily parked it while collecting an item.",
    "abstraction": {
      "state_properties": {
        "exit_cell": {
          "and": [
            "at(11,7)",
            {
              "ge": [
                "freeWidthH",
                6
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          "exit_cell",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  }
]
